"""Seating charts: students in last-name order by row."""

from typing import List, Sequence

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _sort_key(student: Student):
    last, first = student.last_name, student.first_name
    return (last.lower(), first.lower())


def _chunks(items: list, size: int) -> list:
    starts = range(0, len(items), size)
    return [items[i:i + size] for i in starts]


def _row_line(number: int, row: Sequence[Student]) -> str:
    names = " | ".join(s.display_name for s in row)
    return f"Row {number}: {names}"


# ---
def seating_rows(students: Sequence[Student], seats: int):
    if seats <= 0 or not students:
        raise ProjectError("need students and seats")
    ordered = sorted(students, key=_sort_key)
    rows = _chunks(ordered, seats)
    return [_row_line(n, r) for n, r in enumerate(rows, 1)]
